<?php require_once __DIR__.'/conf.php';header('Content-Type: application/json; charset=utf-8');$phone=preg_replace('/[^0-9+]/','',trim($_GET['phone']??''));if($phone===''){echo json_encode(['ok'=>false,'data'=>[]]);exit;}try{$conn->query("CREATE TABLE IF NOT EXISTS admin_orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,source_table VARCHAR(128),source_key VARCHAR(191),customer_name VARCHAR(190) NOT NULL DEFAULT '',phone VARCHAR(60) NOT NULL DEFAULT '',address TEXT,note TEXT,amount DECIMAL(12,2) NOT NULL DEFAULT 0,status VARCHAR(40) NOT NULL DEFAULT 'new',courier_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY source_ref(source_table,source_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$st=$conn->prepare('SELECT id,customer_name,phone,address,note,amount,status,created_at FROM admin_orders WHERE REPLACE(phone," ","")=REPLACE(?," ","") ORDER BY created_at DESC LIMIT 50');$st->bind_param('s',$phone);$st->execute();$r=[];$q=$st->get_result();while($x=$q->fetch_assoc())$r[]=$x;echo json_encode(['ok'=>true,'data'=>$r],JSON_UNESCAPED_UNICODE);}catch(Throwable $e){http_response_code(500);echo json_encode(['ok'=>false,'data'=>[]]);}